        /// <summary>
        /// Folds a block of translations into a language's table. A later block wins — that
        /// is what lets a release's additions live in their own, reviewable dictionary.
        ///
        /// But "wins" was SILENT, and that hid conflicts: the same English phrase translated
        /// two different ways in two blocks, one of them dead text that looks live to anyone
        /// editing it. French had "Mute" as both "Muet" and "Sourdine", Italian as "Muto" and
        /// "Silenzia", Portuguese as "Mudo" and "Silenciar" — only one of each could ever be
        /// shown. An override that CHANGES a value is recorded now, and Live debug reports it.
        /// </summary>
        private static void Merge(Dictionary<string, string> into, Dictionary<string, string> extra,
                                  string lang, string block)
        {
            if (into == null || extra == null) { return; }
            foreach (var kv in extra)
            {
                if (into.TryGetValue(kv.Key, out string had) && !string.Equals(had, kv.Value, StringComparison.Ordinal))
                {
                    _conflicts.Add(lang + ": \"" + Clip(kv.Key) + "\" is \"" + Clip(had) + "\" in one block and \""
                                   + Clip(kv.Value) + "\" in " + block + " (the " + block + " one is shown)");
                }
                into[kv.Key] = kv.Value;
            }
        }

        private static readonly List<string> _conflicts = new List<string>();

        private static string Clip(string s) => s == null ? "" : (s.Length > 40 ? s.Substring(0, 39) + "…" : s);

        // ── Static checks over ALL five tables ───────────────────────────────────
        //
        // The miss counter above only ever knows about phrases that were LOOKED UP, in the
        // ONE language that is active — so a screen nobody opened is never checked, and in
        // English nothing is checked at all (English is the source; there is nothing to
        // look up). These checks read the tables themselves, so they cover every phrase in
        // every language no matter what is on screen or which language is chosen.

        /// <summary>What the static checks found. Computed once; the tables never change at run time.</summary>
        public sealed class TableReport
        {
            /// <summary>Phrases in the largest table — the union of all five.</summary>
            public int Phrases;
            /// <summary>Per language: phrases the OTHER languages translate that this one does not.</summary>
            public Dictionary<Language, List<string>> Missing = new Dictionary<Language, List<string>>();
            /// <summary>Translations whose {0}/{1}… differ from the English they translate.</summary>
            public List<string> PlaceholderMismatches = new List<string>();
            /// <summary>The same English phrase translated two ways (the later block wins).</summary>
            public List<string> Conflicts = new List<string>();
            /// <summary>
            /// Translations that name a control by its ENGLISH caption while that control shows
            /// a translated one — help that points at a button nobody can find.
            /// </summary>
            public List<string> NameDrift = new List<string>();

            public int MissingTotal
            {
                get { int n = 0; foreach (var l in Missing.Values) { n += l.Count; } return n; }
            }

            public bool Clean => MissingTotal == 0 && PlaceholderMismatches.Count == 0 && Conflicts.Count == 0
                                 && NameDrift.Count == 0;
        }

        private static TableReport _tableReport;

        /// <summary>The static checks over all five tables (cached).</summary>
        public static TableReport CheckTables()
        {
            if (_tableReport != null) { return _tableReport; }
            var rep = new TableReport();
            try
            {
                var tables = new[]
                {
                    (Language.Spanish, Es), (Language.French, Fr), (Language.German, De),
                    (Language.Italian, It), (Language.Portuguese, Pt)
                };

                var union = new HashSet<string>(StringComparer.Ordinal);
                foreach (var t in tables) { foreach (string k in t.Item2.Keys) { union.Add(k); } }
                rep.Phrases = union.Count;

                foreach (var t in tables)
                {
                    var missing = new List<string>();
                    foreach (string k in union)
                    {
                        if (!t.Item2.ContainsKey(k)) { missing.Add(k); }
                    }
                    missing.Sort(StringComparer.Ordinal);
                    rep.Missing[t.Item1] = missing;

                    foreach (var kv in t.Item2)
                    {
                        if (!SamePlaceholders(kv.Key, kv.Value))
                        {
                            rep.PlaceholderMismatches.Add(t.Item1 + ": \"" + Clip(kv.Key) + "\" → \"" + Clip(kv.Value) + "\"");
                        }
                        foreach (string english in NamesInText(kv.Value))
                        {
                            if (t.Item2.TryGetValue(english, out string shown) && !string.Equals(shown, english, StringComparison.Ordinal))
                            {
                                rep.NameDrift.Add(t.Item1 + ": \"" + Clip(kv.Value) + "\" calls it \"" + english
                                                  + "\" — on screen it is \"" + shown + "\"");
                            }
                        }
                    }
                }
                rep.Conflicts.AddRange(_conflicts);
            }
            catch (Exception ex) { Logger.Swallow("Localization.CheckTables", ex); }
            _tableReport = rep;
            return rep;
        }

        private static readonly System.Text.RegularExpressions.Regex Placeholder =
            new System.Text.RegularExpressions.Regex(@"\{(\d+)(?:[,:][^}]*)?\}");

        // A quoted name: “…”, "…", «…» or „…“. Single quotes are left out on purpose — in
        // French and Italian they are apostrophes ("l'intervalle") far more often than quotes.
        private static readonly System.Text.RegularExpressions.Regex QuotedName =
            new System.Text.RegularExpressions.Regex("[“\"«„]\\s*([^”\"»“]{2,60}?)\\s*[”\"»“]");

        // The sidebar's page names. Help text refers to them unquoted ("on the Keybinds tab"),
        // so they are looked for as whole words as well.
        private static readonly string[] PageNames =
        {
            "Clicker", "Profiles", "Multi-Point", "Macros", "Statistics", "Keybinds", "Captions", "Settings", "Accounts"
        };

        /// <summary>
        /// English control names a translated sentence mentions: anything it quotes, and the
        /// page names it uses as words. The Macros tab's help, in every language, told people
        /// to tick "Append to selected macro" and assign "Record" on the "Keybinds" tab — in
        /// English, next to a checkbox, two buttons and a tab that all say something else.
        /// </summary>
        private static IEnumerable<string> NamesInText(string translated)
        {
            if (string.IsNullOrEmpty(translated)) { yield break; }
            foreach (System.Text.RegularExpressions.Match m in QuotedName.Matches(translated))
            {
                yield return m.Groups[1].Value.Trim();
            }
            foreach (string page in PageNames)
            {
                // A hyphen AFTER the name still counts — a German compound like "Keybinds-Tab"
                // or "Clicker-Seite" is the page name with a suffix, and an earlier version of
                // this rule stepped over both. A hyphen BEFORE it does not: "Auto-Clicker" is
                // the ordinary word for the kind of program, not the tab.
                if (System.Text.RegularExpressions.Regex.IsMatch(translated,
                        @"(?<![\p{L}\-])" + System.Text.RegularExpressions.Regex.Escape(page) + @"(?!\p{L})"))
                {
                    yield return page;
                }
            }
        }

        /// <summary>
        /// True when the translation uses exactly the placeholders the English does. A value
        /// that drops {1} still formats — it just silently loses that value from the message;
        /// one that adds a {2} the code never passes throws, and F() falls back to English.
        /// </summary>
        private static bool SamePlaceholders(string english, string translated)
        {
            var a = new HashSet<string>(StringComparer.Ordinal);
            var b = new HashSet<string>(StringComparer.Ordinal);
            foreach (System.Text.RegularExpressions.Match m in Placeholder.Matches(english ?? "")) { a.Add(m.Groups[1].Value); }
            foreach (System.Text.RegularExpressions.Match m in Placeholder.Matches(translated ?? "")) { b.Add(m.Groups[1].Value); }
            return a.SetEquals(b);
        }

        /// <summary>
        /// True when <paramref name="shown"/> is English that the active language HAS a
        /// translation for — text that reached the screen without ever being looked up.
        ///
        /// This is the precise form of the question every source scanner approximates. A
        /// scanner reads call sites, so it misses whatever reaches a control by another road:
        /// a string returned in a tuple, a ListView column header, a Text set from a table.
        /// The Script step's "why" phrases were exactly that — translated in all five tables
        /// and shown in English for as long as they existed, because the dialog displayed the
        /// variable instead of looking it up. Checking what controls actually SHOW catches all
        /// of those at once, and a phrase whose translation is the same word ("Tempo", "OK")
        /// is not flagged, because nothing is wrong with it.
        /// </summary>
        /// <summary>
        /// True when text shown in another language still READS as English and has no translation at all —
        /// the half <see cref="ShowsUntranslated"/> cannot see, because that one knows only the phrases the
        /// tables hold. English assembled at run time (pieces appended to a builder, a sentence held in a
        /// variable, an enum's name put into a format) never reaches a table, and the Captions tab's status
        /// lines stayed English in every language that way.
        ///
        /// A heuristic: two different common English words that none of Tempo's other five languages spell
        /// the same way ("for" is Portuguese too, "also" and "was" are German, "a", "no", "in", "on" are
        /// everyone's). A name the user chose can trip it ("Farm the boss and leave"); the layout checks name
        /// the text, so that is easy to tell apart.
        /// </summary>
        public static bool LooksEnglish(string shown)
        {
            if (string.IsNullOrWhiteSpace(shown) || Current == Language.English) { return false; }
            if (IsAlreadyTranslated(shown)) { return false; }
            int hits = 0;
            var seen = new HashSet<string>(StringComparer.Ordinal);
            foreach (System.Text.RegularExpressions.Match m in
                     System.Text.RegularExpressions.Regex.Matches(shown, "[A-Za-z]+(?:'[A-Za-z]+)?"))
            {
                string w = m.Value.ToLowerInvariant();
                if (EnglishMarkers.Contains(w) && seen.Add(w) && ++hits >= 2) { return true; }
            }
            return false;
        }

        private static readonly HashSet<string> EnglishMarkers = new HashSet<string>(StringComparer.Ordinal)
        {
            "the", "and", "to", "of", "is", "are", "were", "be", "been", "it", "its", "it's", "this", "that",
            "these", "those", "your", "you", "you're", "with", "from", "by", "at", "not", "can't", "isn't", "don't",
            "doesn't", "won't", "didn't", "couldn't", "wasn't", "aren't", "which", "what", "when", "while", "than",
            "then", "there", "here", "now", "have", "had", "would", "should", "could", "they", "them",
            "their", "into", "only", "just", "any", "every", "each", "some", "after", "before", "because", "until",
            "about", "nothing", "something", "anything", "again", "already", "yet", "off",
            // Not here although English: "has" (Spanish "you have"), "still" (German "quiet").
        };

        public static bool ShowsUntranslated(string shown)
        {
            if (string.IsNullOrWhiteSpace(shown) || Current == Language.English) { return false; }
            Dictionary<string, string> table = TableFor(Current);
            if (table == null) { return false; }
            if (!table.TryGetValue(shown, out string value) || string.Equals(value, shown, StringComparison.Ordinal))
            {
                return false;
            }
            // A word that is BOTH an English key and a translation in this language is not
            // evidence of anything: German "Profile" is the correct translation of the
            // "Profiles" tab, and is also spelled like the English "Profile". The first run of
            // this check flagged exactly that. Same rule the miss counter uses.
            return !IsAlreadyTranslated(shown);
        }

        /// <summary>
        /// True when <paramref name="shown"/> is one of Tempo's own phrases as the active language shows
        /// it — a translation, or an English source phrase — rather than the user's own data: a profile,
        /// a macro, an audio device, a window title.
        ///
        /// For the layout checks, which measure whether a combo box's choices fit it. Tempo's words are
        /// sized for, and a choice cut off there is a fault; a device called "Speakers (High Definition
        /// Audio Device)" is the user's, and how much of it fits is not a layout bug.
        /// </summary>
        public static bool IsAppText(string shown)
        {
            if (string.IsNullOrWhiteSpace(shown)) { return false; }
            if (Current != Language.English && IsAlreadyTranslated(shown)) { return true; }
            // An English source phrase is a key of the tables (every key is English).
            return Es.ContainsKey(shown) || Fr.ContainsKey(shown) || De.ContainsKey(shown)
                   || It.ContainsKey(shown) || Pt.ContainsKey(shown);
        }

        /// <summary>
        /// Every phrase the ACTIVE language has shown in English this session, in full —
        /// for Live debug's export. The stats line only has room for three.
        /// </summary>
        public static List<string> AllUntranslated()
        {
            lock (_misses)
            {
                var list = new List<string>(_misses);
                list.Sort(StringComparer.Ordinal);
                return list;
            }
        }

