            ["Tempo macros (*.json)|*.json|All files (*.*)|*.*"] = "Macros Tempo (*.json)|*.json|Tous les fichiers (*.*)|*.*",
            ["That barely moved. Hold {0} and sweep a full 360° turn, then release."] = "Cela a à peine bougé. Maintenez {0} et effectuez un tour complet de 360°, puis relâchez.",
            ["This session: {0} tries  ·  avg {1:0.0}  ·  best {2:0.0}"] = "Cette session : {0} essais  ·  moy. {1:0.0}  ·  record {2:0.0}",
