            ["Open release page"] = "Release-Seite öffnen",
            ["Show files"] = "Dateien zeigen",
            ["{0} s"] = "{0} s",
            ["Not checked."] = "Nicht geprüft.",
            ["Not compared."] = "Nicht verglichen.",
