            ["Position:"] = "Position:", ["Opacity:"] = "Deckkraft:",
            ["Show on the badge:"] = "Auf dem Badge anzeigen:",
            ["Click count"] = "Klickanzahl",
            ["Clicks per second (CPS)"] = "Klicks pro Sekunde (CPS)",
