            ["The file isn't a valid Tempo profile."] = "Die Datei ist kein gültiges Tempo-Profil.",
            ["The profile failed validation: {0}"] = "Das Profil hat die Prüfung nicht bestanden: {0}",
            ["Couldn't read the profile: {0}"] = "Das Profil konnte nicht gelesen werden: {0}",
            ["Profile name cannot be empty."] = "Der Profilname darf nicht leer sein.",
            ["Interval must be at least 1 millisecond."] = "Das Intervall muss mindestens 1 Millisekunde betragen.",
            ["Choose a key to auto-press first (Click Options → Set key)."] = "Wähle zuerst die Taste, die gedrückt werden soll (Klickoptionen → Taste…).",
            ["Burst size must be at least 1."] = "Die Klicks pro Salve müssen mindestens 1 sein.",
            ["Burst pause cannot be negative."] = "Die Pause zwischen Salven darf nicht negativ sein.",
            ["Repeat count must be at least 1."] = "Die Anzahl der Wiederholungen muss mindestens 1 sein.",
            ["Run duration must be at least 1 second."] = "Die Laufzeit muss mindestens 1 Sekunde betragen.",
            ["Multi-point mode needs at least one enabled point."] = "Der Mehrpunkt-Modus braucht mindestens einen aktivierten Punkt.",
            ["Interval jitter cannot be negative."] = "Die Intervall-Streuung darf nicht negativ sein.",
            ["Position jitter cannot be negative."] = "Die Positions-Streuung darf nicht negativ sein.",
            ["Click hold time cannot be negative."] = "Die Haltezeit pro Klick darf nicht negativ sein.",
            // Reaching UiFactory rather than T() directly, so the plain missing-key
            // audit cannot see these — they need the choke-point scan.
            ["New profile"] = "Neues Profil",
            ["Favourites only"] = "Nur Favoriten",
            ["Click a card to switch to it. Right-click for more."] = "Klicke auf eine Karte, um zu ihr zu wechseln. Rechtsklick für mehr.",
            ["Name"] = "Name",
            ["Description"] = "Beschreibung",
            ["Shown under the name on the profile card."] = "Wird auf der Profilkarte unter dem Namen angezeigt.",
            ["Icon"] = "Symbol",
            ["Colour tag"] = "Farbmarkierung",
            ["Switch this profile like a mode"] = "Dieses Profil wie einen Modus wechseln",
            ["Also restore my keybinds"] = "Auch meine Tastenbelegungen wiederherstellen",
            ["Also restore my theme, overlay and caption look"] = "Auch mein Design, das Overlay und das Untertitel-Aussehen wiederherstellen",
            ["Ticking these saves your current values into the profile now, and puts them back whenever you activate it. Leave them off and the profile only changes clicking."] = "Wenn du das aktivierst, werden deine aktuellen Werte jetzt im Profil gespeichert und bei jeder Aktivierung wiederhergestellt. Lässt du es aus, ändert das Profil nur das Klicken.",
            ["A simple 100 ms left-click profile."] = "Ein einfaches Profil mit Linksklick alle 100 ms.",
            ["Restore"] = "Wiederherstellen",
            ["Empty the bin"] = "Papierkorb leeren",
            ["The bin is empty."] = "Der Papierkorb ist leer.",
            ["Deleting a profile keeps a copy here so it can be brought back. Restoring one that clashes with a current profile gives it a new name."] = "Beim Löschen eines Profils bleibt hier eine Kopie, damit es zurückgeholt werden kann. Kollidiert ein wiederhergestelltes Profil mit einem aktuellen, erhält es einen neuen Namen.",
            // Off-screen click targets, warned about when a run starts.
            ["Some click points are off-screen"] = "Einige Klickpunkte liegen außerhalb des Bildschirms",
            ["{0} — a monitor may have been unplugged since this profile was saved. Clicks there land on the edge of the screen instead."] = "{0} – seit dem Speichern dieses Profils wurde möglicherweise ein Monitor abgesteckt. Diese Klicks landen stattdessen am Bildschirmrand.",
            // ── Clicker tab: background clicking and run tones. ────────────────
            ["Background Clicking"] = "Klicken im Hintergrund",
            ["Click without moving my cursor"] = "Klicken, ohne meinen Cursor zu bewegen",
            ["Sends each click straight to the window under the target point, so your real pointer stays where it is and you can keep using the PC while Tempo runs. Needs a fixed or multi-point target. Many games ignore posted clicks and only react to a real pointer — leave this off for those."] = "Sendet jeden Klick direkt an das Fenster unter dem Zielpunkt, sodass dein echter Zeiger bleibt, wo er ist, und du den PC weiter benutzen kannst, während Tempo läuft. Erfordert ein festes oder Mehrpunkt-Ziel. Viele Spiele ignorieren gesendete Klicks und reagieren nur auf einen echten Zeiger – lass es dafür aus.",
            ["Sound"] = "Ton",
            ["Beep when clicking starts"] = "Signalton beim Start des Klickens",
            ["Beep when clicking stops"] = "Signalton beim Stoppen des Klickens",
            ["A rising tone to start and a falling one to stop, so a hotkey press is confirmed even with the window hidden in the tray."] = "Ein steigender Ton beim Start und ein fallender beim Stopp, damit ein Tastendruck auch bei im Infobereich verstecktem Fenster bestätigt wird.",
