            ["Lines kept:"] = "Righe:",
            ["Live Captions"] = "Sottotitoli in tempo reale",
            ["Live engine stats and event stream — great for bug reports."] = "Statistiche del motore in tempo reale e flusso di eventi: ottimo per le segnalazioni di bug.",
            ["Match Windows"] = "Come Windows",
            ["Measures it from one 360° turn in your game — far better than guessing."] = "Lo misura da un giro di 360° nel tuo gioco: molto meglio che tirare a indovinare.",
            ["Microphone available:"] = "Microfono disponibile:",
            ["Mirror Windows notifications from other apps (needs permission)"] = "Duplica le notifiche di Windows di altre app (richiede autorizzazione)",
            ["Models folder…"] = "Cartella dei modelli…",
            ["Models…"] = "Modelli…",
            ["Music or sounds playing — no speech"] = "Musica o suoni in riproduzione: nessun parlato",
