            ["Clicking started."] = "Cliques iniciados.",

            // ── Messages that splice a runtime value in through Localization.F ──────
            ["\"{0}\" looks healthy — no stuck keys, no off-screen clicks, no duplicate steps."] = "“{0}” parece estar bem: sem teclas presas, sem cliques fora da tela e sem etapas duplicadas.",
            ["An unexpected error occurred:\n\n{0}"] = "Ocorreu um erro inesperado:\n\n{0}",
            ["Backup failed: {0}"] = "Falha no backup: {0}",
            ["Backup saved to:\n{0}"] = "Backup salvo em:\n{0}",
            ["Bug report copied to your clipboard.\n\nPaste it into an email to {0} (or anywhere else) and add what happened."] = "Relatório de erro copiado para a área de transferência.\n\nCole-o em um e-mail para {0} (ou em qualquer outro lugar) e conte o que aconteceu.",
            ["Calibration couldn't run: {0}"] = "Não foi possível executar a calibração: {0}",
