            ["Couldn't save: {0}"] = "Não foi possível salvar: {0}",
            ["Couldn't start the updater. The new version was downloaded to:\n{0}"] = "Não foi possível iniciar o atualizador. A nova versão foi baixada em:\n{0}",
            ["Couldn't unpack the update."] = "Não foi possível descompactar a atualização.",
            ["Delete macro '{0}'?"] = "Excluir a macro '{0}'?",
