            ["Large Turbo (best all-round, any language)"] = "Large Turbo (o melhor no geral, qualquer idioma)",
            ["1.5 GB · near Large v3 accuracy at several times the speed — the pick for live captions. 90+ languages."] = "1,5 GB · quase a precisão do Large v3 a várias vezes a rapidez — a escolha para legendas em direto. Mais de 90 idiomas.",
            ["Large v3 (most accurate, GPU recommended)"] = "Large v3 (o mais preciso, GPU recomendada)",
            ["2.9 GB · hears the most, decodes the slowest. Realistic only on the GPU engine. 90+ languages."] = "2,9 GB · é o que mais ouve e o que descodifica mais devagar. Só é realista com o motor da GPU. Mais de 90 idiomas.",
            ["Hotkey for {0}"] = "Tecla de atalho para {0}",
            ["Start / Stop (toggle)"] = "Iniciar / Parar (alternar)",
            ["Toggle clicking on and off."] = "Liga e desliga o clique.",
            ["Begin clicking (no effect if already running)."] = "Começa a clicar (sem efeito se já estiver a correr).",
            ["Stop clicking (no effect if already idle)."] = "Para de clicar (sem efeito se já estiver inativo).",
            ["Pause / Resume"] = "Pausar / Retomar",
            ["Pause or resume the current run."] = "Pausa ou retoma a execução atual.",
            ["Pick position"] = "Escolher posição",
            ["Open the on-screen coordinate picker."] = "Abre o seletor de coordenadas no ecrã.",
            ["Emergency stop"] = "Paragem de emergência",
            ["Immediately stop clicking, playback and recording."] = "Para de imediato o clique, a reprodução e a gravação.",
            ["Next profile"] = "Perfil seguinte",
            ["Switch to the next saved profile."] = "Muda para o perfil guardado seguinte.",
            ["Previous profile"] = "Perfil anterior",
            ["Switch to the previous saved profile."] = "Muda para o perfil guardado anterior.",
            ["Increase interval"] = "Aumentar o intervalo",
            ["Add to the click interval on the fly."] = "Acrescenta ao intervalo de clique em tempo real.",
            ["Decrease interval"] = "Reduzir o intervalo",
            ["Subtract from the click interval on the fly."] = "Subtrai ao intervalo de clique em tempo real.",
            ["Toggle always on top"] = "Alternar «sempre visível»",
            ["Pin or unpin the window."] = "Fixa ou desafixa a janela.",
            ["Record macro (toggle)"] = "Gravar macro (alternar)",
            ["Start or stop macro recording."] = "Inicia ou para a gravação da macro.",
            ["Play selected macro"] = "Reproduzir a macro selecionada",
            ["Play the macro selected on the Macros tab."] = "Reproduz a macro selecionada no separador Macros.",
            ["Stop macro playback"] = "Parar a reprodução da macro",
            ["Stop the currently playing macro."] = "Para a macro que está a ser reproduzida.",
            ["Show / Hide window"] = "Mostrar / Ocultar a janela",
            ["Toggle the main window visibility."] = "Alterna a visibilidade da janela principal.",
            ["Show points on screen"] = "Mostrar os pontos no ecrã",
            ["Flash numbered markers at the multi-point targets."] = "Mostra brevemente marcadores numerados nos alvos multiponto.",
            ["Toggle anti-freeze"] = "Alternar o anticongelamento",
            ["Enable or disable anti-freeze protection."] = "Ativa ou desativa a proteção anticongelamento.",
            ["Add point at cursor"] = "Adicionar um ponto no cursor",
            ["Append a multi-point target at the current cursor position."] = "Acrescenta um alvo multiponto na posição atual do cursor.",
            ["Play macro #1"] = "Reproduzir a macro n.º 1",
            ["Play the macro picked in the box beside the key. If none is picked, the 1st macro in the Macros list."] = "Reproduz a macro escolhida na caixa ao lado da tecla. Se nenhuma for escolhida, a primeira macro da lista de Macros.",
            ["Play macro #2"] = "Reproduzir a macro n.º 2",
            ["Play the macro picked in the box beside the key. If none is picked, the 2nd macro in the Macros list."] = "Reproduz a macro escolhida na caixa ao lado da tecla. Se nenhuma for escolhida, a segunda macro da lista de Macros.",
            ["Play macro #3"] = "Reproduzir a macro n.º 3",
            ["Play the macro picked in the box beside the key. If none is picked, the 3rd macro in the Macros list."] = "Reproduz a macro escolhida na caixa ao lado da tecla. Se nenhuma for escolhida, a terceira macro da lista de Macros.",
            ["Toggle Live Captions"] = "Alternar as legendas em direto",
            ["Start or stop live captions, from the source chosen in Settings."] = "Inicia ou para as legendas em direto, com a fonte escolhida em Configurações.",
            ["Arm or disarm camera-relative movement. While armed it takes over W/A/S/D, so it is deliberately off until you press this."] = "Arma ou desarma o movimento relativo à câmara. Enquanto armado assume o controlo de W/A/S/D, por isso está desligado de propósito até premires isto.",
            ["Re-zero the tracked camera direction. Press it while the camera faces your heading - this is the cure for the drift any estimated camera eventually picks up."] = "Repõe a zero a direção da câmara seguida. Prime-o enquanto a câmara aponta para o teu rumo: é a cura para o desvio que qualquer câmara estimada acaba por acumular.",
            ["Second cursor: grab / park"] = "Segundo cursor: agarrar / estacionar",
            ["Grab the second cursor to aim it (it follows your mouse), press again to park it wherever you left it — on either monitor."] = "Agarra o segundo cursor para o apontares (segue o teu rato) e prime outra vez para o estacionares onde o deixaste — em qualquer dos monitores.",
            ["Second cursor: spam-click"] = "Segundo cursor: clique repetido",
            ["Start or stop auto-clicking at the parked second cursor, so it grinds while your real mouse stays free."] = "Inicia ou para o clique automático no segundo cursor estacionado, para que trabalhe enquanto o teu rato real fica livre.",
            ["Play"] = "Reproduzir",
            ["Play once"] = "Reproduzir uma vez",
            ["Pin / Unpin"] = "Fixar / Desafixar",
            ["Toggle On / Off"] = "Ativar / Desativar",
            ["Move to top"] = "Mover para o início",
            ["Move to bottom"] = "Mover para o fim",
            ["View details"] = "Ver detalhes",
            ["Copy row"] = "Copiar linha",
            ["Delete entry"] = "Eliminar entrada",
            ["Second cursor"] = "Segundo cursor",
            ["Change colour…"] = "Mudar a cor…",
            ["Choose 2nd mouse"] = "Escolher o 2.º rato",
            ["Ask by wiggling"] = "Perguntar abanando o rato",
            ["Hide second cursor"] = "Ocultar o segundo cursor",
            ["Grab && place"] = "Agarrar e colocar",
            ["Placing… (click to drop)"] = "A colocar… (clica para largar)",
            ["Spam-click here"] = "Clique rápido aqui",
            ["Stop spam-click"] = "Parar o clique rápido",
            ["Stop spam-click  ·  paused: {0}"] = "Parar o clique rápido  ·  em pausa: {0}",
            ["the second cursor is over Tempo's own window"] = "o segundo cursor está sobre a janela do Tempo",
            ["the window it was aimed at has closed"] = "a janela a que apontava foi fechada",
            ["another window is covering the target"] = "outra janela está a tapar o alvo",
            ["Waiting for a 2nd mouse — click to stop"] = "À espera de um 2.º rato — clica para parar",
            ["Stop using my 2nd mouse"] = "Deixar de usar o meu 2.º rato",
            ["Use my 2nd mouse — plug one in first (experimental)"] = "Usar o meu 2.º rato — liga um primeiro (experimental)",
            ["Use my 2nd mouse (experimental)"] = "Usar o meu 2.º rato (experimental)",
            ["No mice detected"] = "Nenhum rato detetado",
            ["{0} mouse: {1}"] = "{0} rato: {1}",
            ["{0} mice: {1}"] = "{0} ratos: {1}",
            ["Detected: {0}"] = "Detetado: {0}",
            ["{0} is driving the cursor"] = "{0} controla o cursor",
            ["2nd mouse"] = "2.º rato",
            ["now wiggle the mouse you want to use"] = "agora abana o rato que queres usar",
            ["waiting: plug in a 2nd mouse"] = "à espera: liga um 2.º rato",
            ["pick your 2nd mouse above"] = "escolhe o 2.º rato acima",
            ["Aimed at: {0}  ·  clicks: {1}"] = "Alvo: {0}  ·  cliques: {1}",
            ["Click method"] = "Método de clique",
            ["Click method  ·  {0}"] = "Método de clique  ·  {0}",
            ["In the background — your pointer stays free"] = "Em segundo plano — o teu ponteiro fica livre",
            ["Real clicks — for games: your pointer jumps there for each click, only while that game is in front"] = "Cliques reais — para jogos: o teu ponteiro salta para lá em cada clique, só enquanto esse jogo está à frente",
            ["In the background"] = "Em segundo plano",
            ["Real clicks"] = "Cliques reais",
            ["your mouse button is held down"] = "tens um botão do rato premido",
            ["the window it is aimed at isn't in front"] = "a janela a que aponta não está à frente",
            ["Click to capture position  •  Esc or right-click to cancel"] = "Clica para capturar a posição  •  Esc ou clique direito para cancelar",
            ["Couldn't start (raw input or hook unavailable)."] = "Não foi possível iniciar (entrada raw ou hook indisponíveis).",
            ["ARMED everywhere — W/A/S/D captured globally. Arm with the hotkey in-game instead."] = "ARMADO em todo o lado — W/A/S/D capturadas em todo o sistema. Arma-o antes com o atalho dentro do jogo.",
            ["ARMED for the game that was in front. Other windows type normally."] = "ARMADO para o jogo que estava à frente. As outras janelas escrevem normalmente.",
            ["Off. Your keys go straight to the game."] = "Desligado. As tuas teclas vão diretamente para o jogo.",
            ["Couldn't start: {0}"] = "Não foi possível iniciar: {0}",
            ["Disarmed — {0}. Re-arm with the hotkey when you're done."] = "Desarmado — {0}. Arma-o de novo com o atalho quando terminares.",
            ["ARMED · camera estimate re-centred."] = "ARMADO · estimativa da câmara recentrada.",
            ["Caption song lyrics (lets music through, so more stray words)"] = "Legendar letras de canções (deixa passar a música, por isso mais palavras soltas)",
            ["Off (the default): Tempo's voice detection skips stretches of sound with no voice in them — music, a fan, gunfire, a game's menus — before the speech engine hears them, because that is where it invents words. Singing can count as 'no voice', so song lyrics may be skipped too. On: everything with sound is transcribed, lyrics included, and instrumental music can bring stray invented words back. Applies at once."] = "Desligado (predefinição): a deteção de voz do Tempo salta os trechos de som sem nenhuma voz — música, uma ventoinha, tiros, os menus de um jogo — antes de o motor de voz os ouvir, porque é aí que inventa palavras. O canto pode contar como «sem voz», por isso as letras das canções também podem ser saltadas. Ligado: tudo o que tem som é transcrito, letras incluídas, e a música instrumental pode voltar a trazer palavras inventadas soltas. Aplica-se de imediato.",
            ["Open the models folder"] = "Abrir a pasta de modelos",
            ["Get more models from the official site…"] = "Obter mais modelos do site oficial…",
            ["Use a model file from anywhere…"] = "Usar um ficheiro de modelo de qualquer local…",
            ["Already on this PC"] = "Já neste PC",
            ["Found in the models folder"] = "Encontrados na pasta de modelos",
            ["Show details of this model…"] = "Ver detalhes deste modelo…",
            ["Go back to Tempo's own models"] = "Voltar aos modelos do próprio Tempo",
            ["Pop-up notifications"] = "Notificações de pop-up",
            ["Screenshot alerts"] = "Alertas de captura de ecrã",
            ["Settings…"] = "Configurações…",
            ["Check for updates…"] = "Procurar atualizações…",
            ["View source on GitHub"] = "Ver o código no GitHub",
            ["Exit"] = "Sair",
            ["Drag me where you want captions, then turn move mode off"] = "Arrasta-me para onde queres as legendas e depois desliga o modo de movimento",
            ["running…"] = "em execução…",
            ["No clicks recorded yet"] = "Ainda não há cliques registados",
            ["No data yet."] = "Ainda não há dados.",
            ["Waiting for activity…"] = "À espera de atividade…",
            ["(first in the list)"] = "(a primeira da lista)",
            ["(second in the list)"] = "(a segunda da lista)",
            ["(third in the list)"] = "(a terceira da lista)",
            ["Macro for {0}"] = "Macro para {0}",
            ["{0}  (missing)"] = "{0}  (em falta)",
            ["Show small notifications from the tray icon."] = "Mostra pequenas notificações a partir do ícone da área de notificação.",
            ["Show the rounded panel behind captions. Turn this off for a clean text-only look with no background — the text keeps a soft glow so it stays readable."] = "Mostra o painel arredondado por trás das legendas. Desliga isto para um aspeto limpo só com texto e sem fundo — o texto mantém um brilho suave para continuar legível.",
            ["Show which app the audio comes from at the start of the caption bar — '♪ YouTube ·', '♪ Roblox ·', and the app name on the '♪ Music or sounds' note. Untick to hide the tag and keep only the words and speaker labels. Takes effect from the next caption line."] = "Mostra de que aplicação vem o áudio no início da barra de legendas — «♪ YouTube ·», «♪ Roblox ·», e o nome da aplicação na nota «♪ Música ou sons». Desmarca para esconder a etiqueta e manter apenas as palavras e as etiquetas de quem fala. Tem efeito a partir da linha seguinte.",
            ["Single, double, triple or quadruple click each time."] = "Clique simples, duplo, triplo ou quádruplo de cada vez.",
            ["Slightly faster."] = "Ligeiramente mais rápido.",
            ["Slightly slower."] = "Ligeiramente mais lento.",
            ["Softens direction changes. 0 means instant, which is what 'responsive' means — any value above 0 is deliberately adding lag in exchange for a smoother feel. Applied frame-rate independently, so the feel doesn't change with the update rate."] = "Suaviza as mudanças de direção. 0 significa instantâneo, que é o que quer dizer «reativo» — qualquer valor acima de 0 acrescenta atraso de propósito em troca de uma sensação mais suave. Aplicado de forma independente da taxa de fotogramas, por isso a sensação não muda com a taxa de atualização.",
            ["Speech model for Tempo's own captions. Bigger models understand speech better but need more CPU/GPU: Tiny and Base are quick on any PC, Small and Medium hear more accurately, and Large Turbo is the most accurate AND understands 90+ languages automatically. Each model downloads once and then works fully offline."] = "Modelo de voz para as legendas do próprio Tempo. Modelos maiores percebem melhor a fala mas exigem mais CPU/GPU: Tiny e Base são rápidos em qualquer PC, Small e Medium ouvem com mais precisão, e Large Turbo é o mais preciso E percebe automaticamente mais de 90 idiomas. Cada modelo é transferido uma vez e depois funciona totalmente offline.",
            ["Start Tempo automatically every time you sign in to Windows - it opens quietly in the system tray, ready for your hotkeys, or with its window if you tick the option below. Tempo keeps this working even if it's moved to another folder, and it respects Windows' own Startup list: if you switch Tempo off in Task Manager > Startup apps, this box turns itself off to match."] = "Inicia o Tempo automaticamente sempre que inicias sessão no Windows: abre discretamente na área de notificação, pronto para as tuas teclas de atalho, ou com a janela se marcares a opção abaixo. O Tempo mantém isto a funcionar mesmo que seja movido para outra pasta e respeita a própria lista de arranque do Windows: se desativares o Tempo no Gestor de Tarefas > Aplicações de arranque, esta caixa desmarca-se sozinha.",
            ["Start clicking (or use your Start/Stop hotkey)."] = "Começa a clicar (ou usa a tua tecla de atalho Iniciar/Parar).",
            ["Start each spoken turn with \"Speaker 1:\", \"Speaker 2:\" ... Tempo listens to the voice itself (pitch and tone, on your PC - nothing uploaded) so a returning speaker gets their old number back; where the voice can't be told apart it falls back to the rhythm of the conversation, like the >> marks in TV captions. After 30 seconds of silence the numbering starts over at Speaker 1."] = "Começa cada intervenção com «Interlocutor 1:», «Interlocutor 2:»... O Tempo ouve a própria voz (tom e timbre, no teu PC — nada é enviado), por isso quem volta a falar recupera o número anterior; quando não é possível distinguir as vozes, recorre ao ritmo da conversa, como as marcas >> nas legendas de televisão. Após 30 segundos de silêncio a numeração recomeça em Interlocutor 1.",
            ["Start recording mouse and keyboard input."] = "Começa a gravar a entrada de rato e teclado.",
            ["Start with the window hidden in the tray."] = "Inicia com a janela escondida na área de notificação.",
            ["Stop automatically after a set number of clicks."] = "Para automaticamente após um número definido de cliques.",
            ["Stop automatically after a set time."] = "Para automaticamente após um tempo definido.",
            ["Stop clicking."] = "Para de clicar.",
            ["Stop recording."] = "Para a gravação.",
            ["Stop the macro that's playing."] = "Para a macro que está a ser reproduzida.",
            ["Stops a run from clicking or typing into Tempo itself if the cursor is left over this window — it would otherwise tick boxes, switch tabs and hit buttons at full speed. Your own clicks and keys always work, so Stop is never blocked. This also covers the clicker, which never minimises. Turn off only if you deliberately automate Tempo's own interface."] = "Impede que uma execução clique ou escreva dentro do próprio Tempo se o cursor ficar sobre esta janela — caso contrário marcaria caixas, mudaria de separador e carregaria em botões a toda a velocidade. Os teus próprios cliques e teclas funcionam sempre, por isso Parar nunca fica bloqueado. Isto abrange também o clicker, que nunca minimiza. Desliga apenas se automatizares a interface do Tempo de propósito.",
            ["Switch between your saved click profiles."] = "Alterna entre os teus perfis de clique guardados.",
            ["The name used when you save this profile."] = "O nome usado quando guardas este perfil.",
            ["The order the engine visits enabled points each cycle:\n  Sequential - top to bottom, then repeat\n  Reverse - bottom to top, then repeat\n  Random - a different random point each time\n  Ping-Pong - down the list then back up, repeating"] = "A ordem pela qual o motor visita os pontos ativos em cada ciclo:\n  Sequencial - de cima para baixo e repetir\n  Inverso - de baixo para cima e repetir\n  Aleatório - um ponto aleatório diferente de cada vez\n  Ping-Pong - descer a lista e voltar a subir, repetindo",
            ["Turn captions on by themselves when you're watching or playing something with sound: video sites in any browser (YouTube, TikTok, Twitch, Netflix...) and games (Roblox, Call of Duty, Rainbow Six, Fortnite, Valorant...). If you turn captions off during a video, Tempo won't fight you - auto-start re-arms after that video or game stops."] = "Liga as legendas sozinho quando estás a ver ou a jogar algo com som: sites de vídeo em qualquer navegador (YouTube, TikTok, Twitch, Netflix...) e jogos (Roblox, Call of Duty, Rainbow Six, Fortnite, Valorant...). Se desligares as legendas durante um vídeo, o Tempo não te contraria: o arranque automático volta a ficar pronto quando esse vídeo ou jogo terminar.",
            ["Turn on both randomizers with sensible values for less robotic clicking."] = "Ativa ambos os aleatorizadores com valores sensatos para um clique menos robótico.",
            ["Type an exact clicks-per-second target, then press Set to apply it precisely."] = "Escreve um objetivo exato de cliques por segundo e carrega em Definir para o aplicar com precisão.",
            ["Use your own accent colour instead of the theme's."] = "Usa a tua própria cor de destaque em vez da do tema.",
            ["Vary the delay between clicks by a random amount."] = "Varia o atraso entre cliques numa quantidade aleatória.",
            ["Wait this many seconds after pressing Start before the first click. A countdown appears — press Esc or your stop hotkey to cancel it."] = "Espera estes segundos depois de carregar em Iniciar antes do primeiro clique. Aparece uma contagem decrescente — carrega em Esc ou na tua tecla de paragem para a cancelar.",
            ["What Tempo listens to for its own captions. System audio captions whatever your PC plays (needs a speaker). If this PC has no speaker, choose Microphone (or Auto, which switches to the mic automatically)."] = "O que o Tempo ouve para as suas próprias legendas. O áudio do sistema legenda o que o PC reproduz (precisa de um altifalante). Se este PC não tiver altifalante, escolhe Microfone (ou Automático, que muda para o microfone sozinho).",
            ["What to auto-repeat: a mouse button (Left/Right/Middle) or a keyboard key. Pick \"Keyboard key\" to press a key like Space or W at the interval."] = "O que repetir automaticamente: um botão do rato (esquerdo/direito/central) ou uma tecla do teclado. Escolhe «Tecla do teclado» para premir uma tecla como Espaço ou W em cada intervalo.",
            ["When Tempo's own CPU use passes this %, it automatically slows down to keep the system responsive."] = "Quando a utilização de CPU do próprio Tempo ultrapassa esta %, abranda automaticamente para manter o sistema reativo.",
            ["When Windows launches Tempo at sign-in, wait this many extra seconds before its background update check — so it doesn't fight other startup apps for the network. Has no effect when you open Tempo yourself."] = "Quando o Windows inicia o Tempo ao iniciar sessão, espera estes segundos adicionais antes da verificação de atualizações em segundo plano — para não disputar a rede com outras aplicações de arranque. Não tem efeito se abrires o Tempo tu mesmo.",
            ["When captions turn off, save that session's full transcript (with per-line timestamps and speaker labels) as a plain-text file in Tempo's data folder under transcripts\\. Everything stays on your PC - but do remember the file contains whatever was said."] = "Quando as legendas são desligadas, guarda a transcrição completa dessa sessão (com marcas temporais por linha e etiquetas de quem fala) como ficheiro de texto simples na pasta de dados do Tempo, dentro de transcripts\\. Fica tudo no teu PC — mas lembra-te de que o ficheiro contém tudo o que foi dito.",
            ["When off, finished runs aren't saved to your session history and your lifetime totals stop changing — Tempo keeps no record of your activity."] = "Quando está desligado, as execuções terminadas não são guardadas no teu histórico de sessões e os teus totais de sempre deixam de mudar — o Tempo não guarda qualquer registo da tua atividade.",
            ["When you start recording or playing a macro, minimise Tempo so it isn't in the way. Stop with the Record/Stop or Emergency-stop hotkey; the window returns automatically."] = "Ao começares a gravar ou a reproduzir uma macro, minimiza o Tempo para não estorvar. Para com a tecla de atalho Gravar/Parar ou de paragem de emergência; a janela volta automaticamente.",
            ["Which MICROPHONE is used when 'Listen to' is set to Microphone (or Auto falls back to it). With several mics (webcam mic + USB mic), pick the good one. 'Default' follows Windows. Applies immediately; an unplugged choice falls back to the default with a note below."] = "Que MICROFONE é usado quando «Ouvir de» está em Microfone (ou quando Automático recorre a ele). Com vários microfones (o da webcam + um USB), escolhe o bom. «Predefinido» segue o Windows. Aplica-se de imediato; uma escolha desligada recorre ao predefinido com uma nota abaixo.",
            ["Which SPEAKER captions listen through. Tempo hears 'what the PC plays' via this device — with several outputs (headset + monitor speakers), pick the one your videos/games actually play on. 'Default' follows whatever Windows has as its output. Devices are listed by model; a device whose model can't be read shows as 'Unknown speaker'. Applies immediately, and if the chosen device is unplugged, captions fall back to the default and say so below."] = "Através de que ALTIFALANTE as legendas ouvem. O Tempo ouve «o que o PC reproduz» através deste dispositivo — com várias saídas (auscultadores + colunas do monitor), escolhe aquela por onde os teus vídeos/jogos tocam mesmo. «Predefinido» segue o que o Windows tiver como saída. Os dispositivos são listados por modelo; um dispositivo cujo modelo não se consegue ler aparece como «Altifalante desconhecido». Aplica-se de imediato e, se o dispositivo escolhido for desligado, as legendas recorrem ao predefinido e indicam-no abaixo.",
            ["After 30 minutes hidden in the tray with nothing running, global hotkeys and the cursor trail pause, so a forgotten Tempo can't start clicking invisibly. The first press of a paused hotkey only wakes Tempo — a notification says so — and the next press works. Opening the window or starting something from the tray menu wakes it too."] = "Após 30 minutos escondido na área de notificação sem nada a correr, as teclas de atalho globais e o rasto do cursor ficam em pausa para que um Tempo esquecido não comece a clicar de forma invisível. O primeiro toque numa tecla em pausa só acorda o Tempo — uma notificação avisa — e o seguinte já funciona. Abrir a janela ou iniciar algo a partir do menu da área de notificação também o acorda.",
            ["While armed, Tempo intercepts W/A/S/D and sends its own combination instead, steering by the camera direction it has been tracking. It cannot READ the game's camera (that lives in another process) — it estimates it from your mouse movement, so calibrate it first. Bind the 'Camera-relative movement' hotkey to arm it without leaving the game. Emergency stop always disarms it."] = "Enquanto está armado, o Tempo interceta W/A/S/D e envia a sua própria combinação, orientando-se pela direção da câmara que tem vindo a seguir. Não consegue LER a câmara do jogo (vive noutro processo) — estima-a a partir do movimento do rato, por isso calibra primeiro. Atribui a tecla de atalho «Movimento relativo à câmara» para o armar sem sair do jogo. A paragem de emergência desarma-o sempre.",
            ["World-locked: the direction you press is held in WORLD space, so as you swing the camera Tempo re-mixes the keys and you keep travelling the way you aimed — this is what lets you circle-strafe or keep running one way while looking another. Camera-relative pass-through: keys mean camera-space directions, which is what nearly every third-person game already does by itself, so in those games this mode does nothing on purpose."] = "Fixo ao mundo: a direção que premes é mantida no espaço do MUNDO, por isso ao rodar a câmara o Tempo recombina as teclas e continuas a deslocar-te para onde apontaste — é isto que permite fazer strafe circular ou continuar a correr numa direção enquanto olhas para outra. Relativo à câmara sem alterações: as teclas significam direções no espaço da câmara, que é o que quase todos os jogos na terceira pessoa já fazem sozinhos, por isso nesses jogos este modo não faz nada de propósito.",
            ["Write a diagnostic log file. Turn off for extra privacy."] = "Escreve um ficheiro de registo de diagnóstico. Desliga para maior privacidade.",
            ["X coordinate (pixels) for fixed-position clicking."] = "Coordenada X (píxeis) para o clique em posição fixa.",
            ["Y coordinate (pixels) for fixed-position clicking."] = "Coordenada Y (píxeis) para o clique em posição fixa.",
            ["Keep held keys/buttons at their real recorded length when speeding up — so 2× / 4× only shorten the gaps between actions, not a held movement key (WASD). Off = everything scales with speed."] = "Mantém as teclas/botões premidos com a duração real gravada ao acelerar — assim 2× / 4× só encurtam os intervalos entre ações, não uma tecla de movimento mantida (WASD). Desligado = tudo é escalado com a velocidade.",
            ["Glide the pointer to each position instead of jumping. The glide happens in the wait before each move or click, so the macro keeps its recorded timing, and a recording made without mouse movement glides between its clicks too."] = "Desliza o ponteiro até cada posição em vez de saltar. O deslize acontece durante a espera antes de cada movimento ou clique, por isso a macro mantém o ritmo gravado, e uma gravação feita sem movimento do mouse também desliza entre os seus cliques.",
            ["…as camera turns (games)"] = "…como giros de câmera (jogos)",
            ["For games that turn the camera with the mouse — first person, shift lock, holding right-click. Records how far the mouse moved instead of where the pointer was, and plays it back as mouse movement, which is what turns a game's camera. Clicks then happen wherever the pointer is. Leave it off for clicking on screens and menus."] = "Para jogos que giram a câmera com o mouse: primeira pessoa, shift lock, botão direito pressionado. Grava quanto o mouse se moveu em vez de onde o ponteiro estava, e reproduz isso como movimento do mouse, que é o que gira a câmera de um jogo. Os cliques acontecem então onde o ponteiro estiver. Deixe desligado para clicar em telas e menus.",
            ["Keep the Tempo window above other windows."] = "Mantém a janela do Tempo acima das outras.",
            ["Let the Escape key act as an emergency stop."] = "Permite que a tecla Esc funcione como paragem de emergência.",
            ["Live status of the anti-freeze limiter: off, watching, or actively throttling."] = "Estado em direto do limitador anticongelamento: desligado, a vigiar ou a limitar ativamente.",
            ["Live view of the audio devices Tempo can hear through, updated every few seconds. Captions capture 'what the PC is playing' via the speaker shown here; with no speaker, switch \"Listen to\" to Microphone. When a speaker appears or comes back (headphones plugged in, Bluetooth reconnects), running captions recover automatically."] = "Vista em direto dos dispositivos de áudio através dos quais o Tempo pode ouvir, atualizada a cada poucos segundos. As legendas captam «o que o PC está a reproduzir» através do altifalante aqui mostrado; sem altifalante, muda «Ouvir de» para Microfone. Quando um altifalante aparece ou volta (auscultadores ligados, Bluetooth reconectado), as legendas em curso recuperam automaticamente.",
            ["Load a macro from a file and add it to your list."] = "Carrega uma macro a partir de um ficheiro e adiciona-a à tua lista.",
            ["Load macros from a file, adding them to your list."] = "Carrega macros a partir de um ficheiro, adicionando-as à tua lista.",
            ["Make a copy of the selected profile as it was last saved. Save first to include your changes."] = "Faz uma cópia do perfil selecionado tal como foi guardado pela última vez. Guarda primeiro para incluir as tuas alterações.",
            ["Make the Tempo window see-through. 100% is solid; lower values let what's behind show through."] = "Torna a janela do Tempo translúcida. 100% é opaca; valores menores deixam ver o que está por trás.",
            ["Match Windows: with the Light or Dark theme selected, Tempo follows Windows' light/dark mode AND adopts your Windows accent colour, switching live the moment you change either in Windows Settings. Pick a colourful theme (Synthwave, Ocean, …) and it keeps that look untouched. While this is on the theme picker is turned off; a custom accent colour still overrides everything."] = "Acompanhar o Windows: com o tema Claro ou Escuro selecionado, o Tempo segue o modo claro/escuro do Windows E adota a tua cor de destaque do Windows, mudando em direto assim que alterares qualquer um deles nas Definições do Windows. Se escolheres um tema colorido (Synthwave, Ocean, …), esse aspeto mantém-se intacto. Enquanto isto estiver ativo o seletor de temas fica desativado; uma cor de destaque personalizada continua a ter prioridade sobre tudo.",
            ["Maximum random position offset in pixels."] = "Desvio aleatório máximo da posição, em píxeis.",
            ["Maximum random variation added to / removed from the delay (ms)."] = "Variação aleatória máxima somada ou subtraída ao atraso (ms).",
            ["Milliseconds between clicks. The four fields add up to the total delay."] = "Milissegundos entre cliques. Os quatro campos somados dão o atraso total.",
            ["Minutes between clicks."] = "Minutos entre cliques.",
            ["Move the cursor back to where it started when clicking stops."] = "Devolve o cursor ao sítio onde estava quando os cliques param.",
            ["Move the selected point earlier in the order."] = "Move o ponto selecionado para mais cedo na ordem.",
            ["Move the selected point later in the order."] = "Move o ponto selecionado para mais tarde na ordem.",
            ["Nudge each click by a small random offset."] = "Desloca cada clique com um pequeno desvio aleatório.",
            ["Maximum random variation added to / removed from the delay (ms) — never more than the delay allows, so the average speed stays what you set. The hold and the pause between bursts vary with it."] = "Variação aleatória máxima somada ou subtraída ao atraso (ms) — nunca mais do que o atraso permite, para que a velocidade média continue a ser a que definiu. O tempo de cada clique mantido e a pausa entre rajadas variam com ela.",
            ["Maximum random distance from the point, in pixels. Clicks stay on the window under the point."] = "Distância aleatória máxima ao ponto, em píxeis. Os cliques ficam na janela que está sob o ponto.",
            ["Varies the delay and the position a little and holds each click for a natural moment where it was instant, so the clicking looks less robotic. Press again to turn it off."] = "Varia um pouco o atraso e a posição e mantém cada clique premido por um instante natural onde era instantâneo, para que o clique pareça menos robótico. Prima de novo para o desativar.",
            ["Open the clicks-per-second test."] = "Abre o teste de cliques por segundo.",
            ["Pause in milliseconds between bursts (Burst mode)."] = "Pausa em milissegundos entre rajadas (modo Rajada).",
            ["Pick a custom accent colour."] = "Escolhe uma cor de destaque personalizada.",
            ["Pick the caption text colour. Bright yellow reads well over most games. (The bar background always stays transparent.)"] = "Escolhe a cor do texto das legendas. O amarelo vivo lê-se bem sobre a maioria dos jogos. (O fundo da barra permanece sempre transparente.)",
            ["Pick the fixed position by clicking on screen."] = "Escolhe a posição fixa clicando no ecrã.",
            ["Pin the selected macro to the top of the list."] = "Fixa a macro selecionada no topo da lista.",
            ["Play a chime (and show a tray notice) when a fixed-count or fixed-duration run — or a finite macro playback — finishes by itself. Manual stops stay silent."] = "Reproduz um som (e mostra um aviso na área de notificação) quando uma execução de número ou duração fixos — ou uma reprodução finita de macro — termina sozinha. As paragens manuais ficam em silêncio.",
            ["Play a soft beep on each second of the start-delay countdown, and a higher note on GO."] = "Emite um sinal sonoro suave em cada segundo da contagem decrescente do atraso inicial, e uma nota mais aguda no arranque.",
            ["Play the selected macro (Enter)."] = "Reproduz a macro selecionada (Enter).",
            ["Play the selected macro a single time."] = "Reproduz a macro selecionada uma única vez.",
            ["Playback speed. 10 = normal (1.0x), 20 = twice as fast."] = "Velocidade de reprodução. 10 = normal (1,0x), 20 = o dobro da rapidez.",
            ["Quickly set the click rate in clicks per second."] = "Define rapidamente a taxa em cliques por segundo.",
            ["Quickly set the click rate to this preset. The active preset is highlighted."] = "Define rapidamente a taxa para este valor. O valor ativo fica realçado.",
            ["{0} scaling"] = "escala {0}", ["{0} monitors"] = "{0} monitores",
            ["(usable {0}×{1} after the taskbar)"] = "(útil {0}×{1} sem a barra de tarefas)",
            ["Display information isn't available."] = "A informação do ecrã não está disponível.",
            ["Quietly check GitHub for a newer version when Tempo starts, and again while it stays open. A check that fails is tried again a few minutes later."] = "Verifica discretamente no GitHub se existe uma versão mais recente ao iniciar o Tempo, e de novo enquanto ele fica aberto. Uma verificação que falha é repetida alguns minutos depois.",
            ["Remove all points."] = "Remove todos os pontos.",
            ["Remove the selected point (Delete)."] = "Remove o ponto selecionado (Delete).",
            ["Reopen Tempo at the same position and size it had when you last closed it."] = "Reabre o Tempo na mesma posição e tamanho que tinha da última vez que o fechaste.",
            ["Reopen Tempo on the tab you were last using instead of always starting on Clicker. Handy after a long unattended run: if Windows reboots overnight and Tempo restarts with it, you come back to the Macros tab you left it on rather than the Clicker page."] = "Reabre o Tempo no separador que estavas a usar em vez de começar sempre no Clicker. Prático depois de uma execução longa sem vigilância: se o Windows reiniciar durante a noite e o Tempo reiniciar com ele, voltas ao separador Macros onde o deixaste em vez da página do Clicker.",
            ["Run the speech engine on your graphics card (Vulkan — works on AMD, Intel and NVIDIA) instead of the processor. Experimental: on some PCs it's much faster, on others slower than CPU. Takes effect the next time Tempo starts. If the GPU can't keep up with live audio (a game using the card, say), Tempo uses Windows Live Captions for the rest of that session and tries the GPU again the next time it starts — this option stays on. AMD processors always use the normal CPU engine — nothing special needed."] = "Executa o motor de voz na placa gráfica (Vulkan — funciona em AMD, Intel e NVIDIA) em vez do processador. Experimental: nalguns PCs é muito mais rápido, noutros mais lento do que o CPU. Tem efeito no próximo arranque do Tempo. Se a GPU não conseguir acompanhar o áudio em direto (por exemplo, porque um jogo está a usar a placa), o Tempo usa as legendas ao vivo do Windows durante o resto dessa sessão e volta a tentar a GPU no próximo arranque — esta opção mantém-se ligada. Os processadores AMD usam sempre o motor de CPU normal — não é preciso nada de especial.",
            ["Safety limiter that stops Tempo clicking so fast it freezes your PC. Recommended on."] = "Limitador de segurança que impede o Tempo de clicar tão depressa que bloqueie o PC. Recomenda-se deixar ligado.",
            ["Save all your macros to a single file."] = "Guarda todas as tuas macros num único ficheiro.",
            ["Save the current settings (including multi-point list) to this profile."] = "Guarda as definições atuais (incluindo a lista multiponto) neste perfil.",
            ["Save the selected macro to a file you can share or back up."] = "Guarda a macro selecionada num ficheiro que podes partilhar ou usar como cópia de segurança.",
            ["Seconds between clicks."] = "Segundos entre cliques.",
            ["Seconds to wait (3, 2, 1…) before recording starts, so you can switch to the app you want to record. 0 starts immediately."] = "Segundos de espera (3, 2, 1…) antes de a gravação começar, para poderes mudar para a aplicação que queres gravar. 0 começa de imediato.",
            ["Show Tempo's own caption bar (a transparent strip across the bottom of the screen) when you toggle Live Captions with your hotkey. Only the text is visible - it floats over any game and never blocks clicks."] = "Mostra a barra de legendas do próprio Tempo (uma faixa transparente na parte inferior do ecrã) quando ativas as legendas em direto com a tua tecla de atalho. Só o texto é visível: flutua sobre qualquer jogo e nunca bloqueia os cliques.",
            ["Show a small click-through badge on screen while clicking, so you can tell Tempo is running even when its window is hidden."] = "Mostra no ecrã um pequeno emblema que deixa passar os cliques enquanto está a clicar, para saberes que o Tempo está a funcionar mesmo com a janela escondida.",
            ["Burst pause"] = "Pausa entre rajadas",
            ["Click mode"] = "Modo de clique",
            ["Click style"] = "Estilo de clique",
            ["Fixed X"] = "X fixo",
            ["Fixed Y"] = "Y fixo",
            ["Hold each click milliseconds"] = "Milissegundos a manter cada clique",
            ["Interval randomization"] = "Aleatoriedade do intervalo",
            ["Macro loops"] = "Repetições da macro",
            ["Macro speed"] = "Velocidade da macro",
            ["Milliseconds"] = "Milissegundos",
            ["Mouse button"] = "Botão do rato",
            ["Point order"] = "Ordem dos pontos",
            ["Position randomization"] = "Aleatoriedade da posição",
            ["Profile name"] = "Nome do perfil",
            ["Repeat count"] = "Número de repetições",
            ["Repeat seconds"] = "Segundos de repetição",
            ["Search sessions"] = "Procurar sessões",
            ["Start delay seconds"] = "Segundos de atraso ao iniciar",
            ["Add a point by typing its coordinates."] = "Adiciona um ponto escrevendo as suas coordenadas.",
            ["Adds SIGHT to the speaker labels: Windows' built-in on-device face detector watches the video in the foreground window a few times a second, tracks each face, and measures mouth movement - the face whose mouth is moving while speech is heard becomes the active speaker. Nothing is uploaded and nothing is recorded. Costs some CPU; needs the speaker's face visible on screen; it's a hint, not identification."] = "Acrescenta a VISÃO às etiquetas de quem fala: o detetor de rostos integrado do Windows, que corre no próprio dispositivo, observa o vídeo da janela em primeiro plano várias vezes por segundo, segue cada rosto e mede o movimento da boca; o rosto cuja boca se mexe enquanto se ouve fala passa a ser quem está a falar. Nada é enviado nem gravado. Consome algum CPU; precisa que o rosto esteja visível no ecrã; é uma pista, não uma identificação.",
            ["Advanced: raise the speed slider far above the normal limit (up to 2000 CPS). Very fast and CPU-heavy — shows a warning before enabling."] = "Avançado: sobe o cursor de velocidade muito acima do limite normal (até 2000 CPS). Muito rápido e pesado para o CPU — mostra um aviso antes de ativar.",
            ["Also record mouse movement between actions."] = "Grava também o movimento do rato entre ações.",
            ["Always click at one fixed screen position."] = "Clica sempre numa posição fixa do ecrã.",
            ["Anti-jitter. W/A/S/D can only express 8 directions, so a heading sitting exactly on the boundary between two of them would rattle the keys back and forth many times a second. The heading must travel this many degrees PAST a boundary before the keys flip. Raise it if you see chatter; lower it for slightly crisper turns."] = "Anti-oscilação. W/A/S/D só conseguem exprimir 8 direções, por isso um rumo exatamente no limite entre duas delas faria as teclas alternar muitas vezes por segundo. O rumo tem de ultrapassar o limite nestes graus antes de as teclas mudarem. Aumenta se notares tremura; reduz para curvas um pouco mais precisas.",
            ["Apply the exact CPS you typed to the speed slider."] = "Aplica ao cursor de velocidade os CPS exatos que escreveste.",
            ["Ask for confirmation before exiting while clicking is running."] = "Pede confirmação antes de sair enquanto está a clicar.",
            ["Caption text size, in points."] = "Tamanho do texto das legendas, em pontos.",
            ["Capture a point by clicking somewhere on screen."] = "Captura um ponto clicando algures no ecrã.",
            ["Choose a colour theme. Applied instantly."] = "Escolhe um tema de cor. Aplicado de imediato.",
            ["Choose which engine makes the caption text: Windows 11 Live Captions (uses the built-in Windows engine), or Tempo's own offline captions (Tempo listens to your PC audio and transcribes it itself, no internet). Both show in Tempo's caption bar."] = "Escolhe que motor gera o texto das legendas: as legendas em direto do Windows 11 (usa o motor integrado do Windows) ou as legendas offline do Tempo (o Tempo ouve o áudio do PC e transcreve-o sozinho, sem internet). Ambas aparecem na barra de legendas do Tempo.",
            ["Choose which keyboard key to auto-press (only used when the button is set to \"Keyboard key\"). Works with the interval, repeat, humanize and hold-time settings."] = "Escolhe que tecla premir automaticamente (só é usado quando o botão está em «Tecla do teclado»). Funciona com as definições de intervalo, repetição, humanizar e tempo de pressão.",
            ["Clear the selected macro's play count and last-played time."] = "Limpa o número de reproduções e a última reprodução da macro selecionada.",
            ["Click wherever the cursor currently is."] = "Clica onde o cursor estiver nesse momento.",
            ["Closing the window hides it to the tray instead of quitting."] = "Fechar a janela esconde-a na área de notificação em vez de sair.",
            ["Create a new profile with the default settings."] = "Cria um perfil novo com as definições predefinidas.",
            ["Cycle through the points on the Multi-Point tab."] = "Percorre os pontos do separador Multiponto.",
            ["Delete the selected macro (Delete)."] = "Elimina a macro selecionada (Delete).",
            ["Delete the selected profile. You can restore it from the recycle bin on the Profiles tab."] = "Elimina o perfil selecionado. Podes restaurá-lo a partir da reciclagem no separador Perfis.",
            ["Duplicate the selected point (Ctrl+D)."] = "Duplica o ponto selecionado (Ctrl+D).",
            ["Edit the selected point."] = "Edita o ponto selecionado.",
            ["Enable every point, or disable them all if they're all on."] = "Ativa todos os pontos, ou desativa-os todos se já estiverem ativos.",
            ["Enable or disable the selected point."] = "Ativa ou desativa o ponto selecionado.",
            ["Filter the macro list by name."] = "Filtra a lista de macros por nome.",
            ["Flash numbered markers on screen at each point."] = "Mostra brevemente marcadores numerados no ecrã em cada ponto.",
            ["Font for the caption overlay text."] = "Tipo de letra do texto da sobreposição de legendas.",
            ["Gamepad stick deadzone, applied to the stick's overall push rather than to each axis separately — which is what keeps diagonals honest instead of bending them toward the cardinal directions."] = "Zona morta do stick do comando, aplicada ao impulso global do stick e não a cada eixo em separado — é isso que mantém as diagonais fiéis em vez de as desviar para as direções principais.",
            ["Hard ceiling on clicks per second — the engine never clicks faster than this even if the slider asks for more."] = "Limite absoluto de cliques por segundo — o motor nunca clica mais depressa do que isto, mesmo que o cursor peça mais.",
            ["Hold each click's button down for this many milliseconds before releasing. 0 = a normal instant click. Useful for games that need a press-and-hold."] = "Mantém o botão de cada clique premido durante estes milissegundos antes de o largar. 0 = clique instantâneo normal. Útil em jogos que exigem manter premido.",
            ["Hours between clicks."] = "Horas entre cliques.",
            ["How far the game's camera turns for each unit of raw mouse movement. Everything else depends on this number being right. Use Calibrate rather than guessing, and turn OFF in-game mouse acceleration — it breaks the straight-line relationship this relies on."] = "Quanto a câmara do jogo roda por cada unidade de movimento bruto do rato. Tudo o resto depende de este número estar certo. Usa Calibrar em vez de adivinhar e DESLIGA a aceleração do rato no jogo: destrói a relação linear em que isto assenta.",
            ["How fast a fully-pushed right stick turns the camera, in degrees per second. Only matters if you play with a controller; match it to the game's look speed."] = "A que velocidade o stick direito totalmente premido roda a câmara, em graus por segundo. Só importa se jogares com comando; ajusta à velocidade de visão do jogo.",
            ["How many clicks before stopping."] = "Quantos cliques antes de parar.",
            ["How many clicks in each burst (Burst mode)."] = "Quantos cliques em cada rajada (modo Rajada).",
            ["How many seconds to keep clicking."] = "Durante quantos segundos continuar a clicar.",
            ["How many times to repeat. 0 = loop forever."] = "Quantas vezes repetir. 0 = repetir indefinidamente.",
            ["How much the increase/decrease-speed hotkeys change the click interval, in milliseconds."] = "Quanto as teclas de atalho de aumentar/reduzir velocidade alteram o intervalo de clique, em milissegundos.",
            ["How often the automatic check may run: every launch, at most once a day, or at most once a week. While Tempo stays open it checks again at the same pace (twice a day for 'Every launch'). Only applies while the box beside it is ticked."] = "Com que frequência a verificação automática pode correr: em cada arranque, no máximo uma vez por dia ou no máximo uma vez por semana. Enquanto o Tempo fica aberto, volta a verificar ao mesmo ritmo (duas vezes por dia com «A cada início»). Só se aplica enquanto a caixa ao lado estiver marcada.",
            ["How often the movement loop runs. Everything is time-based, so this changes only how finely the camera is tracked — never how fast you move or turn."] = "Com que frequência corre o ciclo de movimento. Tudo é baseado no tempo, por isso isto só altera a finura com que a câmara é seguida — nunca a rapidez com que te moves ou rodas.",
            ["How opaque the caption text is. The bar's background always stays fully transparent."] = "Qual a opacidade do texto das legendas. O fundo da barra permanece sempre totalmente transparente.",
            ["Interface language. Choosing one offers to restart Tempo so it applies everywhere. English, Español, Français, Deutsch, Italiano, Português."] = "Idioma da interface. Ao escolher um, é proposto reiniciar o Tempo para que se aplique em todo o lado. English, Español, Français, Deutsch, Italiano, Português.",
            ["Interval = steady rate. Hold = click only while the button/key is held. Burst = bursts of clicks with a pause between."] = "Intervalo = ritmo constante. Manter = clica apenas enquanto o botão/tecla estiver premido. Rajada = rajadas de cliques com uma pausa entre elas.",
            ["Keep clicking until you stop it."] = "Continua a clicar até o parares.",
            ["When"] = "Quando",
            ["Clicks"] = "Cliques",
            ["Duration"] = "Duração",
            ["Avg CPS"] = "CPS médio",
            ["Time"] = "Tempo",
            ["Detail"] = "Detalhe",
            ["Dwell"] = "Espera",
            ["Rep"] = "Rep",
        };

        private static readonly Dictionary<string, string> Es = new Dictionary<string, string>
        {
            ["Live Captions (accessibility)"] = "Subtítulos en vivo (accesibilidad)", ["Window & Display"] = "Ventana y pantalla", ["Manage"] = "Gestionar",
            ["Clicker"] = "Clic",
            ["Multi-Point"] = "Multipunto",
            ["Macros"] = "Macros",
            ["Statistics"] = "Estadísticas",
            ["Keybinds"] = "Atajos",
            ["Settings"] = "Ajustes",
            ["Click Interval"] = "Intervalo de clic",
            ["Hours"] = "Horas", ["Minutes"] = "Minutos", ["Seconds"] = "Segundos", ["Millis"] = "Milis",
            ["Total delay between clicks. Minimum 1 ms."] = "Retraso total entre clics. Mínimo 1 ms.",
            ["Click Options"] = "Opciones de clic",
            ["Button"] = "Botón", ["Type"] = "Tipo", ["Mode"] = "Modo",
            ["Click Position"] = "Posición de clic",
            ["Current cursor position"] = "Posición actual del cursor",
            ["Fixed position"] = "Posición fija",
            ["Multi-point (see Multi-Point tab)"] = "Multipunto (ver pestaña Multipunto)",
            ["Restore cursor position when stopped"] = "Restaurar la posición del cursor al detener",
            ["Repeat"] = "Repetir",
            ["Until stopped"] = "Hasta detener", ["Fixed count:"] = "Cantidad fija:", ["For (seconds):"] = "Durante (s):",
            ["Burst Settings"] = "Ajustes de ráfaga", ["Clicks per burst"] = "Clics por ráfaga", ["Pause (ms)"] = "Pausa (ms)",
            ["Randomization (anti-pattern)"] = "Aleatorización (anti-patrón)",
            ["Randomize interval  ±"] = "Aleatorizar intervalo  ±", ["Randomize position  ±"] = "Aleatorizar posición  ±",
